insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9010, 20, 'Jugendtreffs und offene Jugendarbeit erhalten, ausbauen und verlässlich finanzieren (Land)', 'Schließungen von Jugendclubs (London 2010–2019) verschlechterten nachweislich Schulleistungen und erhöhten Jugendkriminalität. Ohne Zielgröße oder Betrag bleibt offen, wie viele Orte gesichert werden; Fachkräfte sind knapp.', 'belegt', 'https://www.iser.essex.ac.uk/research/publications/publication-588442', 'land', null, true, 'blind'),
  (9011, 20, 'Jugendarbeit gesetzlich absichern: Rechtsanspruch, Pflichtaufgabe oder verbindliche Mindeststandards (Land)', 'Verbindliche Vorgaben schützen Angebote vor Kürzungen; Berlin setzt seit 2022 Mengen- und Qualitätsstandards, eine Wirkungsauswertung fehlt. Mehrkosten trägt das Land (Konnexität), Fachkräfte sind knapp.', 'offen', 'https://www.berlin.de/sen/jugend/jugend/jugendarbeit/', 'land', null, true, 'blind'),
  (9012, 20, 'Mobile Jugendarbeit und mobile Jugendzentren im ländlichen Raum fördern (Land)', 'Mobile Angebote erreichen Jugendliche, wo es keinen festen Treff gibt. Eine Wirkungsevaluation aus Österreich zeigt aber auf dem Land deutlich weniger Kontakte als in Städten und vor allem Jungen als Nutzer.', 'gemischt', 'https://austria-forum.org/web-books/jugendarbeit00de2017isds/000062', 'land', null, true, 'blind'),
  (9013, 20, 'Queere Jugendzentren und queere Jugendorte erhalten und ausbauen (Land)', 'Studien verbinden die Teilnahme an queeren Jugendangeboten mit weniger psychischer Belastung der Teilnehmenden. Sie erreichen aber nur einen kleinen Teil der Jugendlichen und schaffen kaum allgemeine Treffpunkte.', 'belegt', 'https://shine.lab.uconn.edu/wp-content/uploads/sites/3321/2021/06/eisenberg_lgbtq_orgs_2020_annals.pdf', 'land', null, true, 'blind'),
  (9014, 20, 'Jugendgerechte Treffpunkte im öffentlichen Raum und in Leerständen mit Jugendlichen gestalten (Land)', 'Setzt am häufig geäußerten Wunsch nach Treffpunkten im öffentlichen Raum an; Modellvorhaben des Bundes zeigen Nutzen von Beteiligung. Belastbare Wirkungsstudien fehlen, Konflikte mit Anwohnenden bleiben möglich.', 'offen', 'https://www.bbsr.bund.de/BBSR/DE/forschung/programme/exwost/Forschungsfelder/2009/JugendlicheImStadtquartier/01_Start.html', 'land', null, true, 'blind'),
  (9015, 20, 'Kulturpass mit Guthaben für junge Menschen fortführen (Bund)', 'Guthaben senkt Kosten kultureller Freizeit, der Bund hat es bereits umgesetzt. Beim französischen Vorbild prüfte der Rechnungshof: Es verstärkt vor allem bestehende Gewohnheiten und erreicht Jugendliche aus ärmeren Familien seltener.', 'gemischt', 'https://www.livreshebdo.fr/article/pass-culture-la-cour-des-comptes-epingle-le-dispositif', 'bund', null, true, 'blind'),
  (9016, 20, 'Bund finanziert kommunale Jugendzentren und Jugendfreizeitinfrastruktur mit (Bund)', 'Jugendclubs wirken nachweislich; mehr Geld für Kommunen kann Schließungen verhindern. Der Bund kann aber nur über Investitions- und Förderprogramme beitragen, laufende Jugendarbeit ist Sache von Ländern und Kommunen.', 'belegt', 'https://www.iser.essex.ac.uk/research/publications/publication-588442', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
