insert into public.abdeckung (thema_id, partei_id, land, art, begruendung, stand, ki_entwurf, durchsucht_fuer) values
  (20, 11, null, 'keine', 'Inhaltsverzeichnis, Kapitel Familie/Kinder und Jugendliche (S. 62-66), Sport (S. 60-61) und Fundstellen S. 26, 72, 79 gelesen; nichts zu Jugendtreffs, Teilhabekosten für Freizeit oder Nutzungskonflikten im öffentlichen Raum. Grep nach Freizeit, Jugend, Spielplatz, Lärm, Treffpunkt ohne passende Zusage.', '2026-10-08', true, '{2001,2002,2003}'),
  (20, 11, 'BE', 'massnahmen', null, '2026-10-08', true, '{2001,2003}'),
