  (20, 12, null, 'keine', 'Kapitel 9 (Familien, S. 25-28), Kapitel 18 (Kultur und Sport, S. 49-52), Kapitel 19 (S. 52-54) und Fundstellen S. 4, 7, 24, 26, 30, 32, 35, 53 gelesen; keine Zusage zu Jugendtreffs, Jugendarbeit, Freizeitkosten oder Nutzungskonflikten im öffentlichen Raum.', '2026-10-08', true, '{2001,2002,2003}'),
  (20, 12, 'BE', 'massnahmen', null, '2026-10-08', true, '{2001,2003}'),
