  (20, 14, null, 'keine', 'Erfasste Stellen (S. 32) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-08', true, '{2001,2002,2003}'),
  (20, 14, 'BE', 'massnahmen', null, '2026-10-08', true, '{2001,2003}'),
  (20, 14, 'MV', 'keine', 'Inhaltsverzeichnis, Kapitel Kommunen (S. 75-77), Kinder-/Jugendrechte (S. 109), kulturelle Bildung (S. 107-108), Ehrenamt (S. 121-122) und alle Fundstellen (S. 19, 35, 49, 75, 107, 108, 112) gelesen; keine konkrete Zusage zu Jugendtreffs, Freizeitangeboten für Jugendliche oder Nutzungsregeln im öffentlichen Raum.', '2026-10-08', true, '{2001,2003}'),
  (20, 14, 'ST', 'massnahmen', null, '2026-10-08', true, '{2001,2003}'),
  (20, 15, null, 'keine', 'Kapitel ''Familie und Demografie'' (S. 145-156), ''Kultur und Medienpolitik'' (S. 171-177) und Volltextsuche nach Jugend, Freizeit, Treffpunkt, Sport, Lärm, Musikschul gelesen; alle Fundstellen S. 15, 68, 69, 92, 155, 175 sind Zufallstreffer (Umsatzsteuer, Bargeld, Bitcoin, Energie, Familienmediation, Rundfunk). Nichts zu Jugendtreffs, Teilhabekosten oder Nutzungskonflikten.', '2026-10-08', true, '{2001,2002,2003}'),
  (20, 15, 'BE', 'massnahmen', null, '2026-10-08', true, '{2001,2003}'),
  (20, 15, 'MV', 'keine', 'Familien-/Jugendkapitel (S. 19-23), Schule/Sport (S. 32-33), ÖPNV (S. 70), Kultur (S. 91-92) und Fundstellen (S. 2, 8, 13, 82-84, 90) gelesen; nichts zu Jugendtreffs, Freizeitorten für Jugendliche oder Lärm-/Raumregeln. Fundstellen sind Fehltreffer (Inhaltsverzeichnis, Photovoltaik, Wirtschaft, Windkraft).', '2026-10-08', true, '{2001,2003}'),
  (20, 15, 'ST', 'keine', 'Kapitel ''Familie und Kinder'' (S. 10-22) und Fundstelle S. 112 gelesen, dazu Volltextsuche nach Jugendzentrum, Jugendarbeit, Jugendliche, Treffpunkt, Freizeit, Skate, Bolzplatz, Spielplatz, Lärm; nichts setzt an Jugendtreffpunkten (2001) oder Nutzungskonflikten im öffentlichen Raum (2003) an.', '2026-10-08', true, '{2001,2003}'),
